const readAnswer = function researchResult({ response }) {
  const answer = response?.choices?.[0]?.message?.content;
  if (typeof answer !== 'string' || !answer.trim()) throw new Error('Perplexity returned no answer text.');
  const citations = response.citations ?? [];
  if (!Array.isArray(citations) || citations.some((citation) => typeof citation !== 'string')) throw new Error('Perplexity citations must be a string array.');
  return { output: answer, citations };
}

return $input.all().map((item,index)=>({json:readAnswer({response:item.json}),pairedItem:{item:index}}));

const prepare = function researchRequest({ user_prompt, system_prompt, domains }) {
  if (typeof user_prompt !== 'string' || !user_prompt.trim()) throw new Error('A research question is required.');
  if (typeof domains !== 'string') throw new Error('Provide a comma-separated domain list.');
  const filters = domains.split(',').map((domain) => domain.trim()).filter(Boolean);
  if (!filters.length) throw new Error('At least one search domain is required.');
  if (system_prompt != null && typeof system_prompt !== 'string') throw new Error('System instructions must be text.');
  return { request: {
    model: 'sonar',
    messages: [
      { role: 'system', content: system_prompt?.trim() || 'Answer the question using retrieved sources. Cite sources and distinguish facts from uncertainty.' },
      { role: 'user', content: user_prompt.trim() },
    ],
    temperature: 0.2, top_p: 0.9, search_domain_filter: filters,
    search_recency_filter: 'month', return_images: false,
    top_k: 0, stream: false, presence_penalty: 0, frequency_penalty: 1,
  } };
}

return $input.all().map((item,index)=>({json:prepare(item.json),pairedItem:{item:index}}));
